/* Every sandbox run is written to admin_audit: this is the only tool that
   executes code, so "who ran what, and was it refused" has to be answerable
   after the fact. Best effort - never fails the caller. */
const auditRun = async (detail) => {
  // Returns a status instead of swallowing: a silent audit failure is worse
  // than a visible one, because "we have a log" becomes a lie.
  try {
    const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY || '', 'Content-Type': 'application/json' };
    if (!$env.N8N_API_KEY) return 'failed: N8N_API_KEY missing';
    const list = await this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/api/v1/data-tables?limit=100', headers: H, timeout: 10000 });
    const t = (list.data || []).find((x) => x.name === 'admin_audit');
    if (!t) return 'failed: admin_audit table not found';
    await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/api/v1/data-tables/' + t.id + '/rows', headers: H, body: { data: [{ action: 'run_python', target: 'chat', detail: String(detail).slice(0, 400) }] }, timeout: 10000 });
    return 'ok';
  } catch (eA) {
    return 'failed: ' + String((eA && eA.message) || eA).slice(0, 160);
  }
};

/* ---- run_python approvals -------------------------------------------------
   The sandbox refuses network / subprocess / file writes. Refusing outright
   would make the tool useless for those jobs, so instead the code is parked
   here and pushed to the owner with allow/deny buttons. Approval is keyed by
   the sha256 of the exact code: you approve what actually runs, not a
   description of it. 15-minute TTL, single use. */
const APPROVE_TTL_MS = 15 * 60 * 1000;
