const requestApproval = async (codeHash, why, code) => {
  const id = await dtId('sandbox_approvals');
  if (!id) throw new Error('sandbox_approvals table missing');
  const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY || '', 'Content-Type': 'application/json' };
  const existing = await dtRows(id, { type: 'and', filters: [{ columnName: 'code_hash', condition: 'eq', value: codeHash }] });
  const fresh = existing.find((r) => r.status === 'pending' && (!r.expires_at || new Date(r.expires_at).getTime() > Date.now()));
  if (fresh) return fresh.id;
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://localhost:5678/api/v1/data-tables/' + id + '/rows', headers: H,
    body: { data: [{ code_hash: codeHash, why: why || '', snippet: String(code).slice(0, 500), status: 'pending', requested_at: new Date().toISOString(), expires_at: new Date(Date.now() + APPROVE_TTL_MS).toISOString() }] },
    timeout: 10000,
  });
  const rows = await dtRows(id, { type: 'and', filters: [{ columnName: 'code_hash', condition: 'eq', value: codeHash }] });
  const made = rows.find((r) => r.status === 'pending');
  return made ? made.id : 0;
};

/* ---- outbound MCP -------------------------------------------------------
   The platform exposes an MCP server; this is the other direction — calling
   tools on servers the owner registered. Only HTTP transports, and only
   servers in the mcp_servers table: the model can use them but never add
   them, same rule as workflow tools. */
const mcpServer = async (name) => {
  const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY || '', 'Content-Type': 'application/json' };
  const list = await this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/api/v1/data-tables?limit=100', headers: H, timeout: 10000 });
  const t = (list.data || []).find((x) => x.name === 'mcp_servers');
  if (!t) throw new Error('mcp_servers table missing');
  const rows = await this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/api/v1/data-tables/' + t.id + '/rows', qs: { limit: 50, filter: JSON.stringify({ type: 'and', filters: [{ columnName: 'name', condition: 'eq', value: String(name) }] }) }, headers: H, timeout: 10000 });
  const row = (rows.data || [])[0];
  if (!row) throw new Error('unknown mcp server: ' + name);
  if (!(row.enabled === 1 || row.enabled === true)) throw new Error('mcp server disabled: ' + name);
  return row;
};
// Streamable HTTP may answer with JSON or with SSE; accept both.
const mcpPost = async (url, authHeader, payload) => {
  const headers = { 'Content-Type': 'application/json', Accept: 'application/json, text/event-stream' };
  if (authHeader) headers.Authorization = authHeader;
  const raw = await this.helpers.httpRequest({ method: 'POST', url, headers, body: payload, timeout: 30000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  const text = typeof raw.body === 'string' ? raw.body : JSON.stringify(raw.body || '');
  const dataLines = text.split('\n').filter((l) => l.indexOf('data:') === 0).map((l) => l.slice(5).trim());
  const candidates = dataLines.length ? dataLines : [text];
  for (const cand of candidates) {
    try {
      const j = JSON.parse(cand);
      if (j && (j.result || j.error)) return j;
    } catch (e) {}
  }
  return { error: { message: 'unparsable MCP response: ' + text.slice(0, 200) } };
};

