        method: 'POST',
        url: 'http://n8n-sandbox:8000/run',
        headers: { 'x-sandbox-key': $env.CHAT_API_KEY || '', 'Content-Type': 'application/json' },
        body: { code, timeout: 15, allow_network: !!allowNetwork },
        timeout: 30000,
      });

      // A human may already have approved this exact code (hash-keyed, 15 min,
      // one shot). That is the only way past the sandbox guard.
      const approved = await findApproval(codeHash);
      if (approved) {
        const resp = await callSandbox(true);
        await consumeApproval(approved.id);
        await auditRun(JSON.stringify({ why, ok: !!resp.ok, approved: true, blocked: !!resp.blocked, chars: code.length }));
        result = {
          type: 'python',
          results: {
            approved: true, ok: !!resp.ok, exit_code: resp.exit_code,
            stdout: String(resp.stdout || '').slice(0, 4000),
            stderr: String(resp.stderr || '').slice(0, 1000),
          },
        };
      } else {
        const resp = await callSandbox(false);
        const blocked = !!(resp && resp.blocked);
        const detail = {
          ok: !!resp.ok, exit_code: resp.exit_code,
          stdout: String(resp.stdout || '').slice(0, 4000),
          stderr: String(resp.stderr || '').slice(0, 1000),
          blocked, reason: resp.reason || '', message: resp.message || '',
        };
        if (blocked) {
          const reqId = await requestApproval(codeHash, why, code);
          try {
            await this.helpers.httpRequest({
              method: 'POST',
              url: 'http://localhost:5678/webhook/internal/notify',
              headers: { Authorization: AUTH_HEAD + ($env.CHAT_API_KEY || ''), 'Content-Type': 'application/json' },
              body: {
                kind: '代码审批',
                message: '模型想执行一段被拦下的代码（' + (resp.reason || '受限操作') + '）。'
                  + String.fromCharCode(10) + '原因：' + (why || '未说明')
                  + String.fromCharCode(10) + '--- 代码前 300 字 ---'
                  + String.fromCharCode(10) + code.slice(0, 300),
                actions: [{ label: '允许执行一次', kind: 'ap', id: reqId }, { label: '拒绝', kind: 'rj', id: reqId }],
              },
              timeout: 15000,
            });
            detail.approval_requested = true;
            detail.request_id = reqId;
            detail.hint = '这段代码需要人工批准，已推送给机主。机主点「允许执行一次」之后，请用与本次完全相同的代码（一个字符都不要改）再调用一次 run_python —— 网关会自动放行，不需要传任何额外参数。批准 15 分钟内有效、只能执行一次；代码只要改动一个字符就需要重新批准。';
          } catch (eN) {
            detail.approval_requested = false;
            detail.hint = '推送审批失败：' + String((eN && eN.message) || eN).slice(0, 80);
          }
        }
        result = { type: 'python', results: detail };
        await auditRun(JSON.stringify({ why, ok: !!resp.ok, blocked, reason: resp.reason || '', chars: code.length }));
      }
    } else if (it.tool_name && it.tool_name.indexOf('wf_') === 0) {
      const nm = it.tool_name.slice(3);
      const list = await wfList();
      const wf = list.find((t) => t.name === nm);
      if (!wf) throw new Error('unknown workflow tool: ' + nm);
      const resp = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/' + wf.path, headers: { Authorization: AUTH_HEAD + ($env.CHAT_API_KEY || ''), 'Content-Type': 'application/json' }, body: { source: 'chat', name: nm, text: String((it.args && it.args.text) || '').slice(0, 1000), ts: new Date().toISOString() }, timeout: 90000 });
      const rs = typeof resp === 'string' ? resp : JSON.stringify(resp);
      result = { type: 'wf', results: { status: 200, body: String(rs).slice(0, 2000) } };
    } else {
      result = { type: 'unknown', error: 'unknown tool: ' + it.tool_name };
    }
  } catch (e) {
    result = { error: String(e && e.message ? e.message : e).slice(0, 200) };
  }
  if (__idem && result && !result.error) await idemWrite(__idem, it, result);
  }
  const { tool_calls, ...rest } = it;
  out.push({ json: { ...rest, result, __trace: {
    round: (it.tool_state && it.tool_state.round) || 1,
    tool: String(it.tool_name || ''),
    ms: Date.now() - __t0,
    ok: !!(result && !result.error),
    replayed: !!__cached,
    idem: __idem ? String(__idem).slice(0, 12) : '',
    args: JSON.stringify(it.args || {}).slice(0, 200),
    /* The sandbox refusal has to be visible in the trace, not only in the
       prose: without it the evaluator cannot tell an honest "blocked"
       answer from a model that made up a success. */
    blocked: !!(result && result.results && result.results.blocked),
    reason: String((result && result.results && result.results.reason) || '').slice(0, 80),
    ...((result && result.crag) ? { crag_grade: String(result.crag.grade || ''), crag_action: String(result.crag.action || '') } : {}),
    ...((result && result.type === 'web_fetch') ? { web_fetch_ok: !!result.ok, web_fetch_host: (function () { try { return new URL(String(result.url || '')).hostname; } catch (e) { return ''; } })().slice(0, 120), web_fetch_chars: Number(result.chars) || 0, web_fetch_reason: String(result.reason || '') } : {}),
  } } });
}
return out;

/* Aggregate tool results into tool messages and build the next upstream
   payload. After MAX_ROUNDS the follow-up request omits tools entirely,
   forcing a final answer. Tool failures become error tool messages so the
   model can answer without that tool instead of the workflow failing. */
const items = $input.all().map((i) => i.json);
const MAX_ROUNDS = Number($env.MAX_TOOL_ROUNDS || 2);
/* Appended on the final request, the one sent after we drop the tool list.
   The model has no way to know its tools were taken away, so without this it
   keeps reasoning as if it could still look something up and answers from
   thin air. Naming the constraint gives it permission to say "I don't have
   enough" — which is strictly better than a confident guess. */
const BUDGET_NOTE = '【工具预算已用完】本轮及之后不能再调用任何工具，请只依据上面已获得的工具结果回答。如果已有信息足以回答，就正常回答，不要向用户提及预算。如果不足以给出可靠答案，明确说明「信息不足」、缺的是什么，并给出下一步建议 —— 不要猜测、不要编造事实。';


/* Round 2 reuses round 1's server tool array verbatim. A second literal here
   used to drift (it was missing run_python / mcp_* and every wf_* tool), which
   silently shrank the tool surface after the first tool round. */
const first = items[0] || {};
const serverTools = first.server_tools || [];
const round = first.tool_state?.round ?? 1;

const toolMsgs = items.map((it) => {
  const res = it.result || {};
  let content;
  if (res.error) {
    content = JSON.stringify({ query: it.query, error: res.error });
  } else if (res.type === 'kb') {
    content = JSON.stringify({ tool: it.tool_name, sources: res.results, ...(res.web && res.web.length ? { web_supplement: res.web } : {}), ...(res.crag ? { evidence_grade: res.crag.grade } : {}) });
  } else if (res.type === 'web') {
    /* empty + notice must reach the model: a 0-row web result is a signal about
       the search backend, not a fact about the world. */
    content = JSON.stringify({ tool: it.tool_name, results: res.results, ...(res.empty ? { empty: true, notice: res.notice || '', unresponsive_engines: res.unresponsive_engines || [] } : {}) });
  } else if (res.type === 'web_fetch') {
    /* Forward the full fetched text + provenance on success, or the legible
       reason on failure. The text is already sanitized/clamped/delimiter-wrapped
       by fetchWebPage; the model treats it as untrusted quoted data (DIRECTIVE 10). */
    content = JSON.stringify({ tool: it.tool_name, ok: !!res.ok, url: res.url, ...(res.ok ? { title: res.title, text: res.text, chars: res.chars, fetched_at: res.fetched_at, source: res.source } : { reason: res.reason }) });
  } else {
    content = JSON.stringify({ tool: it.tool_name, results: res.results });
  }
  return { role: 'tool', tool_call_id: it.tool_call_id, content };
});

const messages = [...(first.messages_base || []), ...toolMsgs];
const wrappedUp = round >= MAX_ROUNDS;
if (wrappedUp) messages.push({ role: 'system', content: BUDGET_NOTE });
const upstreamPayload = {
  model: first.model,
  messages,
  stream: false,
  ...(first.llm_params || {}),
};
const clientTools = first.client_tools || null;
if (round < MAX_ROUNDS) upstreamPayload.tools = [...serverTools, ...(clientTools || [])];

/* Per-round tool trace: which tool, how long, did it fail, was it a replay.
   Accumulated across rounds so chat_executions can answer "what did this
   turn actually do" instead of just "it used 2 rounds". */
const roundTrace = items.map((it) => it.__trace).filter(Boolean);
const prevState = first.tool_state || {};
const nextState = { ...prevState, round, trace: [...(prevState.trace || []), ...roundTrace] };
return [{ json: { upstream_payload: upstreamPayload, tool_state: nextState, client_tools: clientTools, server_tools: serverTools, llm_params: first.llm_params || {}, idempotency_key: first.idempotency_key || '', session_id: first.session_id || '' } }];
